<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; class Company extends Model{use HasFactory; protected $fillable=['external_id','legal_name','trade_name','document','country','state','city','segment','website','priority','status','score','notes','last_update']; protected function casts():array{return ['last_update'=>'datetime','score'=>'integer'];} public function opportunities(){return $this->hasMany(Opportunity::class);} public function contacts(){return $this->hasMany(Contact::class);} public function activities(){return $this->hasMany(Activity::class);} public function works(){return $this->hasMany(Work::class);} public function evidences(){return $this->hasMany(Evidence::class);}}
